  insert into public.brands (name, website, description, country, status) values ('LYMA', 'https://us.lyma.life', 'Premium beauty-tech brand behind the LYMA Laser and Laser PRO at-home cold-laser devices plus skincare and supplement starter kits; its own Professional partner program pays clinics and partners 20% on devices and 10% on kits, with an FAQ that states there is no cap on earnings.', 'United States', 'published') returning id into bid;
