  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'LYMA Professional Affiliate Partner Program', 'https://us.lyma.life/pages/professional', 'https://us.lyma.life/pages/professional', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://us.lyma.life/pages/professional', 'official_site', 'affiliate', 'LYMA''s own Professional page publishes its commission table (LYMA Laser $2,695 at 20% = $539; Laser PRO $5,995 at 20% = $1,199; Skincare & Supplement Starter Kits at 10%), a 90-day credit window after a client clicks, automatic monthly payment, and the FAQ answer to ''How much can I earn?'': ''There''s no cap. 20% on every Laser and 10% across skincare and supplements, for as long as your clients keep buying.'' The program is pitched to clinics and professionals, and the page gives professional@lyma.life for support. Earnings cap is therefore recorded as uncapped on the brand''s own explicit statement.', 'verified', now());
