  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 13, 19, 13, 8, 5, '{"niche_fit": "FDA-cleared at-home laser devices with dramatic 30-day before/after imagery are proven skincare-UGC material, though the program is framed around clinics.", "ugc_evidence": "A structured own-site partner program with email templates, talking points, assets and tracked recommendations; no hard creator count was published.", "compensation": "20% on devices worth $2,695-$5,995 ($539-$1,199 per sale) and 10% on kits, with the brand''s own FAQ stating ''There''s no cap'' \u2014 the strongest verified-uncapped economics in this round.", "contact_access": "Published partner email (professional@lyma.life) plus the full program page on the brand''s own US site.", "opportunity_availability": "Applications are open on the brand''s page with no minimum referrals or targets, but approval is aimed at professionals and clinics.", "credibility": "Peer-reviewed clinical backing (Aesthetic Surgery Journal), 50 global patents, TIME Best Inventions and major beauty-award recognition."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Tallowtan', 'https://www.tallowtan.com', 'Grass-fed tallow self-tan brand (three DHA shades at $89) shipping to Canada, the US, Australia and New Zealand; runs a Creator Program on UpPromote with a UGC Creator path and an Affiliate Partner path, a free jar every month a creator posts four times, and an FAQ stating there is no cap on earnings — but its own page conflicts on the rate (20% flat in the headline and terms, 15% in the FAQ).', 'Canada', 'published') returning id into bid;
