  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Tallowtan Creator Program (UpPromote)', 'https://www.tallowtan.com/pages/creator-program', 'https://www.tallowtan.com/pages/creator-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.tallowtan.com/pages/creator-program', 'official_site', 'affiliate', 'Tallowtan''s own Creator Program page states ''There is no cap on earnings'' and, in its tracking FAQ, ''commission is calculated at 15% per sale with no cap'' — so the earnings cap is recorded as uncapped on explicit brand statements. However the same page''s headline and terms sections state ''20% flat on every sale you drive, at every tier'', an unresolved conflict with the FAQ''s 15%, so no single commission rate is recorded (rate null). Applications run through UpPromote; creators get a free full-size jar on approval and another each month they post four times.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.tallowtan.com/pages/creator-program', 'official_site', 'ugc_collab', 'The page defines a dedicated UGC Creator path (''You make the content and we use it in our ads, site and emails'') with usage rights and raw files, TikTok/Instagram Reels content, gifted product plus commission, and welcomes micro- and nano-creators in its FAQ.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.tallowtan.com/pages/creator-program', 'official_site', 'creator_saturation', 'No Beacons brand page or other hard creator count for Tallowtan surfaced in this research, so creator saturation is recorded as unknown rather than estimated.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 16, 12, 9, 8, 3, '{"niche_fit": "Tallow-based self-tan with shade-matching and before/after application content is a natural short-form skincare format.", "ugc_evidence": "An explicit UGC Creator track whose content the brand uses in ads, plus gifted product monthly \u2014 strong structured creator evidence on the brand''s own page.", "compensation": "Earnings are explicitly uncapped (stated twice), but the page conflicts on the rate itself (20% flat in the terms vs 15% in the FAQ), so no rate is recorded and compensation scores mid-range.", "contact_access": "Applications run through the brand''s own program page into UpPromote; no partnerships email is published.", "opportunity_availability": "Open applications; the header asks for 1,000+ followers on TikTok or Instagram while the FAQ says no minimum is required \u2014 an inconsistency to confirm at sign-up.", "credibility": "Small, young DTC brand with a 30-day guarantee and free CA/US shipping; no retail distribution or press record verified."}'::jsonb);
