  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://shop.prohairlabs.com/professional-hair-labs-affililate-program/', 'official_site', 'affiliate', 'Professional Hair Labs'' own affiliate page states ''You get an unlimited number of referrals and no commission caps'' and ''You get a clean 10% commission for all user purchases within the cookie lifetime'', with a dedicated affiliate manager and applications approved within 24 hours — the no-cap statement is explicit, so the cap is recorded as uncapped. Caveats on the same page: the program is sold with an annual affiliate subscription (''Limited-Time Offer: Sign Up Now & Save 50% Of Your Annual Affiliate Subscription''), and the fetched copy of the page is dated 2021 with an April 2026 crawl, so current terms should be confirmed at sign-up. The page publishes info@prohairlabs.com, +1 800 778 4247 and the Zephyrhills, Florida address.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://shop.prohairlabs.com/professional-hair-labs-affililate-program/', 'official_site', 'creator_saturation', 'No Beacons brand page or other hard creator count for Professional Hair Labs surfaced in this research, so creator saturation is recorded as unknown rather than estimated.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 20, 10, 11, 11, 6, 3, '{"niche_fit": "Wig and hairpiece adhesives serve a real but narrow beauty niche (wig creators and wearers).", "ugc_evidence": "An influencer-addressed affiliate program with affiliate testimonials on the page; no creator count was published.", "compensation": "10% commission with an explicit ''no commission caps'' statement (verified uncapped), reduced by the annual affiliate subscription the program charges.", "contact_access": "Published email, phone and street address on the program page, plus a dedicated affiliate manager.", "opportunity_availability": "Applications are reviewed within 24 hours, but the paid annual subscription is a barrier most programs in this round do not have.", "credibility": "Established niche manufacturer claiming 10,000+ company customers; the program page itself is dated, so terms need re-confirmation."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('The Golden Secrets', 'https://www.thegoldensecrets.com', 'Founder-led clean skincare brand (Jesse Golden) whose affiliate community page promises ''Grow your income by earning commission on sales. No cap on commissions!'', personal evergreen discount codes, monthly product bonuses and a private affiliate community, with applications handled through Refersion; no commission percentage is published on the page.', 'United States', 'published') returning id into bid;
