  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'The Golden Secrets Affiliate Program (Refersion)', 'https://thegoldensecrets.refersion.com', 'https://www.thegoldensecrets.com/en-au/pages/test', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.thegoldensecrets.com/en-au/pages/test', 'official_site', 'affiliate', 'The Golden Secrets'' own affiliate page (live on the brand''s official domain, though the page is titled ''test'') lists under Program Outline + Perks: ''Grow your income by earning commission on sales. No cap on commissions!'' — an explicit no-cap statement, so the cap is recorded as uncapped. The page''s Apply Here link leads to the brand''s Refersion registration (thegoldensecrets.refersion.com); no commission percentage is published on the page, so the rate is recorded as null. The page also notes monthly posting requirements and a minimum sales threshold to remain an active affiliate.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.thegoldensecrets.com/en-au/pages/test', 'official_site', 'ugc_collab', 'The same page describes a creator community model: personal evergreen discount codes, monthly product bonuses on top of commission, exclusive perks and a private Instagram affiliate page — structured UGC/affiliate collaboration evidence from the brand itself.', 'verified', now());
