  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 10, 9, 7, 4, '{"niche_fit": "Clean, glow-led skincare with a strong founder story is well suited to routine and results UGC.", "ugc_evidence": "A defined affiliate community with codes, bonuses and a private creator group described on the brand''s own page; no hard creator count was published.", "compensation": "''No cap on commissions!'' is explicit (verified uncapped), but no percentage is published on the page, so the rate is unknown.", "contact_access": "Applications run from the brand''s page into its Refersion registration; no partnerships email is published.", "opportunity_availability": "Open application via Refersion, with monthly posting and minimum-sales requirements to stay active; the source page''s ''test'' title suggests it may be a staging page, so confirm at sign-up.", "credibility": "Established founder-led clean-beauty brand with a long-running product line and press presence."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('CUSKIN', 'https://www.cuskin.com.au', 'Australian dermatologist-developed cosmeceutical skincare brand whose affiliate program is launching now: founding partners lock in 20% commission (standard rate 15% afterwards), a 30-day cookie, monthly bank payouts from A$100, and an FAQ stating ''There is no cap on earnings'' — applications require a valid Australian Business Number (ABN).', 'Australia', 'published') returning id into bid;
