  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'CUSKIN Affiliate Program (launch / founding partners)', 'https://www.cuskin.com.au/affiliate-program', 'https://www.cuskin.com.au/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.cuskin.com.au/affiliate-program', 'official_site', 'affiliate', 'CUSKIN''s own affiliate page FAQ answers ''How much can I earn?'' with ''You earn 20% commission on every sale made through your referral link... There is no cap on earnings'' — an explicit no-limit statement, so the cap is recorded as uncapped. The 20% is a limited-time launch rate (standard 15% afterwards; early affiliates keep 20% while active). The page also publishes a 30-day cookie, A$100 minimum payout, monthly bank transfer, and an application requirement of a valid Australian ABN plus an active social presence.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.cuskin.com.au/affiliate-program', 'official_site', 'creator_saturation', 'The page states ''We''re launching our affiliate program and offering our founding partners an exclusive 20% commission rate'' — a brand-new program still recruiting its founding cohort, which is absolute evidence of low creator saturation at this time.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 12, 16, 9, 7, 3, '{"niche_fit": "Dermatologist-developed cosmeceuticals with A$80-150 average orders fit ingredient- and results-led skincare UGC.", "ugc_evidence": "A new program explicitly recruiting influencers and creators alongside clinics and salons; the cohort is still forming, so published creator evidence is thin.", "compensation": "20% launch commission (15% standard later) with an explicit ''no cap on earnings'' FAQ answer \u2014 verified uncapped; A$100 payout threshold applies.", "contact_access": "Application form on the brand''s own site with personal review in 2-3 business days; no partnerships email is published.", "opportunity_availability": "Applications are open now for founding partners, but a valid Australian ABN is required, which limits it to Australian creators.", "credibility": "Small, newly launching Australian brand; dermatologist-developed positioning but no verified retail distribution yet."}'::jsonb);
