  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://auraviafitness.com/affiliates', 'official_program_page', 'creator_program', 'Programme is built for fitness creators and influencers: no follower minimum, no exclusivity, creator assets and early product access, free product for qualifying creators; contact email info@auraviafitness.com with the subject line ''affiliate''.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 17, 17, 11, 9, 2, '{"compensation": "15% standard rate (20% on the first sale and again after EUR 2,000 lifetime referred sales), with explicit no-cap wording in both the hero terms and the FAQ.", "contact_access": "Published affiliate email (info@auraviafitness.com) with subject-line guidance on the official page.", "credibility": "The page names a registered UK company (AURAVIA RESEARCH LTD, England and Wales) with a London address, but the brand is young and little-known, so credibility stays low.", "niche_fit": "Compact home-fitness gear (walking pads, adjustable dumbbells) is a natural demo and review fit for fitness and home-workout creators.", "opportunity_availability": "Open application on the brand''s own page with no follower minimum.", "ugc_evidence": "Official page is explicitly built for fitness creators with assets, early access and free product, but publishes no creator counts, so the score stays mid-range."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Muscle & Strength', 'https://www.muscleandstrength.com', 'Large US sports-nutrition and supplement store carrying 7,000+ products. Its long-running affiliate program is partnered with Commission Junction (CJ Affiliate) and pays a flat 10% commission on all referred orders, with no cap on earnings stated in its official FAQ.', 'United States', 'published') returning id into bid;
