  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 15, 16, 5, 9, 5, '{"compensation": "Flat 10% on all orders with an explicit no-cap statement in the official FAQ; a mid-range rate on a very large catalogue.", "contact_access": "No direct partnerships email is published on the page; contact runs through the CJ network application.", "credibility": "Long-established US supplement retailer running its program through CJ Affiliate, a major network.", "niche_fit": "One of the largest supplement catalogues in the niche (7,000+ products), so almost any fitness creator''s audience products are covered.", "opportunity_availability": "Free, open signup via CJ on the official page.", "ugc_evidence": "Runs through CJ with standard affiliate creative (banners, links, data feeds); the page does not publish creator counts or UGC-specific terms, so saturation stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Campervan Planet', 'https://www.campervanplanet.com', 'Worldwide campervan rental booking platform. Its own affiliate program pays a rising share of the net profit on every confirmed booking (30% rising to 50%), with ready-made links, banners, widgets, an embeddable search box and a live per-post analytics panel, and states there is no cap on earnings.', null, 'published') returning id into bid;
