  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Campervan Planet Affiliate Program', 'https://www.campervanplanet.com/affiliate-program', 'https://www.campervanplanet.com/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.campervanplanet.com/affiliate-program', 'official_program_page', 'affiliate_program', 'Official FAQ: ''You start at 30% of our net profit per booking and rise to 50% as you drive more bookings. The more your content converts, the more you earn, with no cap.'' Note the commission is a share of net profit, not of the booking price.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.campervanplanet.com/affiliate-program', 'official_program_page', 'creator_program', 'Toolkit for creators: deep links, banners, widgets, an embeddable search box and source-labelled links that show exactly which post brought each booking; links work on social media, newsletters and videos - no website required.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.campervanplanet.com/affiliate-program', 'official_program_page', 'affiliate_program', 'Published contact on the affiliate page: hello@campervanplanet.com, plus phone numbers for the US, New Zealand, Australia, the UK and Canada.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 14, 15, 11, 9, 3, '{"compensation": "30% of net profit rising to 50%, explicitly uncapped; scored below a straight percentage-of-sale rate because the base is net profit, not booking value.", "contact_access": "Published partnerships email (hello@campervanplanet.com) on the official affiliate page.", "credibility": "Operating booking platform with worldwide supplier coverage and published phone contacts, but a smaller name than the major travel networks.", "niche_fit": "Campervan and road-trip content is a strong, visual fit for travel creators, and the program is worldwide.", "opportunity_availability": "Free signup in about a minute; affiliate code activated within 48 hours.", "ugc_evidence": "Creator tooling is unusually concrete (per-post source labels, widgets, banners), but no creator counts are published, so saturation stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Shirt Tucker', 'https://www.shirt-tucker.com', 'Single-product fashion accessory brand selling a $19.99 rubber shirt-stay belt that keeps shirts tucked in all day. Its affiliate program, powered by Endorsely, is built for short-form video creators and pays 25% commission per sale with no sales cap, instant links and no minimum followers.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
