  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Shirt Tucker Affiliate Program (Endorsely)', 'https://shirt-tucker-e077.endorsely.com', 'https://www.shirt-tucker.com/influencer.html', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shirt-tucker.com/influencer.html', 'official_program_page', 'affiliate_program', 'Official page states ''25% Commission - You earn 25% on every sale ($5 per sale)... no cap, no tiers'', a ''No Sales Cap'' (infinity) badge, and the FAQ answers: ''There is no cap on how many sales you can make or how much you can earn.'' 30-day cookie, $20 payout minimum, monthly payouts by PayPal or bank transfer.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shirt-tucker.com/influencer.html', 'official_program_page', 'creator_program', 'Program is designed for TikTok, Reels and Shorts creators: no minimum followers, link issued instantly, video playbooks and hooks library, free product for creators with 5,000+ followers or after the first sale, plus a 20% audience discount code.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shirt-tucker.com/influencer.html', 'official_program_page', 'affiliate_program', 'Scale signals on the official page: the brand claims 10,000+ users and its Amazon listing shows a 4.4 rating from 32 ratings - a small, young brand.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 17, 19, 4, 10, 3, '{"compensation": "25% per sale ($5 on the $19.99 product) with explicit no-cap wording in the hero terms and FAQ - one of the clearest uncapped statements found this round.", "contact_access": "No email or contact is published on the page; joining runs through the Endorsely signup link.", "credibility": "Small single-product brand; its own page claims 10,000+ users but the linked Amazon listing has only 32 ratings.", "niche_fit": "A single, demonstrable wardrobe-fix product at $19.99 - narrow but very easy for fashion and workwear creators to show on camera.", "opportunity_availability": "Instant link on signup, no minimum followers, no approval step described.", "ugc_evidence": "The official page is written for short-form video creators, with playbooks, hooks and free-product rules; no creator counts are published, so saturation stays unknown."}'::jsonb);
