  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.bookaway.com/affiliates', 'official_program_page', 'affiliate_program', 'Program terms on the official page: 30-day attribution cookies, payment once commissions reach $50, monthly payments, wire transfer or PayPal, W-9/W-8BEN uploaded to the platform, and a personal account manager for affiliates.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.bookaway.com/affiliates', 'official_program_page', 'affiliate_program', 'Company details printed on the affiliate page for invoicing: Bookaway LTD, HaTa''as St 6, Ramat Gan 5251247, Israel.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 14, 13, 6, 9, 5, '{"compensation": "Unlimited earning potential is stated, but the rate is 5% of the revenue share of a booking rather than of the booking price, so the effective take is modest and the wording is ambiguous.", "contact_access": "A personal account manager is promised after signup, but no direct email is published on the page.", "credibility": "Established travel-tech platform (60k+ routes, 24-hour support) with full company invoicing details printed on the page.", "niche_fit": "Ground transport in 110+ countries fits almost any travel itinerary content, especially Asia and Latin America routes.", "opportunity_availability": "Free signup on the official page, subject to team approval.", "ugc_evidence": "The page explicitly invites travel websites, blogs and popular social media pages; no creator counts are published, so saturation stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('ProofofOnward', 'https://www.proofofonward.com', 'Onward-ticket proof service for visas and border checks, issuing real, verifiable airline PNRs. Its own affiliate program pays 25% commission on every referred sale with a 60-day cookie, monthly payouts, and a personal 10%-off code for the affiliate''s audience, and its FAQ states there is no cap on earnings.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 25, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://www.proofofonward.com/affiliate.', 'https://www.proofofonward.com/affiliate', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'ProofofOnward Affiliate Program', 'https://www.proofofonward.com/affiliate', 'https://www.proofofonward.com/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.proofofonward.com/affiliate', 'official_program_page', 'affiliate_program', 'Official FAQ: ''You earn 25% of what the customer pays on every booking made through your referral link or with your personal discount code. There''s no cap - the more you refer, the more you earn.'' Commissions become payable 30 days after the order; monthly payouts at a $50 minimum via PayPal or bank transfer; 60-day attribution.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.proofofonward.com/affiliate', 'official_program_page', 'creator_program', 'Program is pitched at travel bloggers, digital-nomad communities, visa consultants, travel agencies, YouTubers and creators; every affiliate gets a personal 10%-off audience code that credits sales even without a link click; applications are reviewed by hand with a reply usually within 1 business day.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 14, 19, 4, 8, 3, '{"compensation": "25% of the customer price on every sale with an explicit ''There''s no cap'' FAQ answer - a high rate for travel services.", "contact_access": "No email is published on the page; contact is via the application form.", "credibility": "The product is verifiable-PNR based and the page is transparent about rules and prohibited promotion, but the brand is small and niche.", "niche_fit": "A narrow but real need - proof of onward travel for visas and border checks - that maps directly onto nomad, backpacker and expat content.", "opportunity_availability": "Free application with manual review, usually answered within 1 business day.", "ugc_evidence": "The page names creators and YouTubers as target partners and supports video/podcast attribution via personal codes; no creator counts published, so saturation stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('iliTrip', 'https://www.ilitrip.com', 'Marketplace where creators sell curated travel itineraries. Its own affiliate program pays 20% on standard trips (10% on founding-creator trips) with a 30-day cookie and Stripe payouts, no minimum audience, and an explicit no-earning-cap policy. The program is brand new - its own page showed zero active affiliates and zero sales at research time.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 20, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: low (see evidence). Rate as reported by https://www.ilitrip.com/affiliates.', 'https://www.ilitrip.com/affiliates', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'iliTrip Affiliate Program', 'https://www.ilitrip.com/affiliates', 'https://www.ilitrip.com/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.ilitrip.com/affiliates', 'official_program_page', 'affiliate_program', 'Official page: ''No earning cap - promote unlimited trips to unlimited people'', and the FAQ answers ''How much can I earn?'' with ''No cap - the more you share, the more you earn.'' Rates: 20% on standard trips, 10% on founding-creator trips; 30-day cookie; Stripe payouts.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.ilitrip.com/affiliates', 'official_program_page', 'affiliate_program', 'Saturation evidence from the brand''s own live counters on the affiliate page at research time: 0 active affiliates, 3 total clicks, 0 sales generated and $0 paid out - a brand-new, effectively empty program.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.ilitrip.com/affiliates', 'official_program_page', 'creator_program', 'Open to anyone (''No minimum audience size... whether you have 100 or 100,000 followers''); free 30-second signup, unique links per trip, marketing assets provided, links work across Instagram, TikTok, YouTube, blogs and email.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 16, 17, 4, 9, 2, '{"compensation": "20% on standard trips (10% on founding-creator trips) with explicit no-cap wording in the terms block and FAQ.", "contact_access": "No email or named contact is published on the page; signup is self-serve.", "credibility": "Credibility is low for now: the brand''s own page shows 0 sales generated and $0 paid out, so the marketplace has no proven transaction volume yet.", "niche_fit": "Affiliates promote itineraries made by travel creators, so the product itself is creator content - a natural fit for travel UGC.", "opportunity_availability": "Free, instant signup with no minimum audience.", "ugc_evidence": "Program is creator-first (per-trip links, assets, no audience minimum) and its own counters show zero active affiliates, which supports a low-saturation mark."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Arnold Training App', 'https://arnoldtrainingapp.com', 'AI workout-plan app that builds personalised training and nutrition plans. Its own affiliate program pays 20% of net revenue on each referred plan purchase, recurring for as long as the referral keeps paying, with no approval step and Stripe payouts. The site''s own footer states it is an independent AI tool and is not affiliated with Arnold Schwarzenegger.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fitness'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 20, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://arnoldtrainingapp.com/become-affiliate.', 'https://arnoldtrainingapp.com/become-affiliate', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Arnold Training App Affiliate Program', 'https://arnoldtrainingapp.com/become-affiliate', 'https://arnoldtrainingapp.com/become-affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://arnoldtrainingapp.com/become-affiliate', 'official_program_page', 'affiliate_program', 'Official page: affiliates earn 20% of net revenue (after Stripe/Apple fees) on each plan purchase by a referred user, recurring while the referral keeps paying; terms list ''No cap'' and ''No cap on earnings'', and the FAQ answers ''Is there a cap on how much I can earn?'' with ''There is no cap.''', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://arnoldtrainingapp.com/become-affiliate', 'official_program_page', 'affiliate_program', 'Joining terms on the official page: no approval process - sign up for a free account, copy the referral link from the dashboard and share it; payouts via Stripe; worldwide.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://arnoldtrainingapp.com/become-affiliate', 'official_program_page', 'affiliate_program', 'Credibility caveat printed in the site''s own footer: ''Arnold Training App is an independent AI tool and is not affiliated with Arnold Schwarzenegger.''', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 18, 4, 10, 2, '{"compensation": "20% of net revenue per referred plan, recurring while the referral pays, with an explicit ''There is no cap'' FAQ answer; scored below gross-revenue rates because the base is net of platform fees.", "contact_access": "No email or contact is published on the page; everything runs through the app dashboard.", "credibility": "The site itself discloses it is an independent AI tool not affiliated with Arnold Schwarzenegger, so the famous name must not be read as an endorsement; scored low on credibility.", "niche_fit": "A workout-plan app is an easy fit for fitness creators'' programming and transformation content.", "opportunity_availability": "No approval step - the link is issued on free-account signup.", "ugc_evidence": "Self-serve creator link with dashboard tracking, but the page shows no creator community, assets or counts, so saturation stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Khanum''s', 'https://khanums.co', 'London-based luxury modest-fashion and bridal label (Khanum''s Ltd) recruiting fashion-forward content creators as affiliates. Creators join through the brand''s LTK network and receive 10% on every order, with the brand stating there is no cap on commissions.', 'United Kingdom', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'LTK', 10, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: low (see evidence). Rate as reported by https://khanums.co/pages/affiliate-program.', 'https://khanums.co/pages/affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Khanum''s Affiliate Program (LTK)', 'https://khanums.co/pages/affiliate-program', 'https://khanums.co/pages/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://khanums.co/pages/affiliate-program', 'official_program_page', 'affiliate_program', 'Official affiliate page: ''Receive 10% on every order you generate'' and, under ''No Limits on Earnings'', ''The more you share, the more you earn, there''s no cap on commissions.'' Joining is via the page''s ''JOIN OUR LTK NETWORK'' button (creator.shopltk.com).', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://khanums.co/pages/affiliate-program', 'official_program_page', 'creator_program', 'The page recruits ''fashion-forward content creators'' and lists content formats it wants: styling reels, try-on hauls, modest styling tips, bridal features and behind-the-scenes content; affiliates get a unique tracking link/code and monthly payouts.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://universe.beacons.ai/brands/khanums', 'third_party_directory', 'affiliate_program', 'Beacons'' brand directory lists 29 creators who have posted for Khanum''s all time - a small absolute creator count that supports a low-saturation mark.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://uk.trustpilot.com/review/www.khanums.co?page=10', 'third_party_directory', 'affiliate_program', 'Trustpilot company details list Khanum''s Ltd at E1, London, United Kingdom, describing it as a British Bangladeshi brand creating timeless investment pieces.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 15, 15, 4, 8, 3, '{"compensation": "10% on every order with explicit ''no cap on commissions'' wording on the official page; a standard rate, lifted by the uncapped term.", "contact_access": "No email is published on the affiliate page; application runs through LTK.", "credibility": "A real London label (Khanum''s Ltd) with press and retail presence, but a small affiliate operation run through LTK.", "niche_fit": "Luxury modest fashion and bridal is a defined, underserved creator niche with strong occasionwear content angles.", "opportunity_availability": "Open application via the LTK network button on the official page.", "ugc_evidence": "The brand names the exact UGC formats it wants (styling reels, try-on hauls, bridal features) and Beacons shows only 29 creators have ever posted for it, supporting low saturation."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Baja Beach Co', 'https://bajabeach.co', 'Beach-lifestyle brand selling coordinated beach essentials and accessories. It runs both an affiliate program and a brand ambassador program for creators: affiliates earn a percentage on every sale with monthly payments and no cap on earnings, though the percentage itself is not published; ambassadors also receive free products and promo codes.', null, 'published') returning id into bid;
