  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', null, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://bajabeach.co/pages/affiliate-program-ambassadors.', 'https://bajabeach.co/pages/affiliate-program-ambassadors', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Baja Beach Co Affiliate & Ambassador Program', 'https://bajabeach.co/pages/affiliate-program-ambassadors', 'https://bajabeach.co/pages/affiliate-program-ambassadors', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://bajabeach.co/pages/affiliate-program-ambassadors', 'official_program_page', 'affiliate_program', 'Official page: ''Earn commissions: Earn a percentage on every sale generated from your link. Payments are made monthly, and there''s no cap on how much you can earn!''', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://bajabeach.co/pages/affiliate-program-ambassadors', 'official_program_page', 'affiliate_program', 'The percentage rate itself is not published anywhere on the official page - it is described only as ''competitive commission rates'' - so commission_rate is recorded as null rather than guessed.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://bajabeach.co/pages/affiliate-program-ambassadors', 'official_program_page', 'ambassador_program', 'Ambassador track on the same page: free products, exclusive discounts and personalised promo codes, co-branded content and sponsored-post opportunities; open to creators, bloggers and influencers of any size who post beach, lifestyle and fashion content.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 15, 10, 4, 8, 3, '{"compensation": "Uncapped earnings are stated explicitly, but the commission percentage is not published anywhere on the page, so compensation scores low until the rate is confirmed at application.", "contact_access": "No email is published on the page; questions go through the site''s contact form.", "credibility": "Operating storefront with a defined two-track creator program, but a small brand with unpublished commercial terms.", "niche_fit": "Beach essentials and accessories fit summer, travel and lifestyle fashion content well.", "opportunity_availability": "Open application form on the official page, reviewed by the team.", "ugc_evidence": "Both an affiliate program and a content-focused ambassador program (free product, co-branded content, sponsored posts); no creator counts published, so saturation stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Seeking Health', 'https://www.seekinghealth.com', 'Supplement brand selling practitioner-formulated vitamins and supplements, running Affiliate and Ambassador partner programs for health practitioners, certified health coaches and influencers.', null, 'published') returning id into bid;
