  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Seeking Health Affiliate & Ambassador Programs', 'https://www.seekinghealth.com/pages/affiliate-program', 'https://www.seekinghealth.com/pages/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.seekinghealth.com/pages/affiliate-program', 'official_site', 'affiliate', 'Seeking Health''s official affiliate page headlines ''earn unlimited commissions'' and a section titled ''Uncapped Commissions'', stating rates start at 15% and affiliates can earn up to 20% and more, with a 60-day cookie window, free product samples and a monthly personalized 10%-off coupon code for followers. The starting rate of 15% is recorded; the cap is verified uncapped on the brand''s own wording.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.seekinghealth.com/pages/affiliate-program', 'official_site', 'contact', 'The same official page publishes affiliate@seekinghealth.com twice in its FAQ for program-fit and general affiliate questions, and describes a four-step join process (choose Affiliate or Ambassador, apply, get approved, start earning) with payment within the first two weeks of each month.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 14, 19, 13, 8, 4, '{"niche_fit": "Practitioner-grade supplements are a core health-creator niche, and the program explicitly recruits influencers as well as practitioners and coaches.", "ugc_evidence": "A public partner page recruiting influencers, with free product for campaign promotion, though no creator counts were published on fetched pages.", "compensation": "Verified uncapped commissions starting at 15% and rising to 20% and more - among the strongest supplement terms found.", "contact_access": "Published affiliate@seekinghealth.com program email on the official page.", "opportunity_availability": "Application with brand approval; two tracks (Affiliate or Ambassador).", "credibility": "Established supplement brand with a structured partner program and educational institute offering; founding details were not on the fetched page, so held at 4."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('IM8 Health', 'https://im8health.com', 'Daily all-in-one nutrition powder brand co-founded with David Beckham, selling an NSF-certified daily essentials formula positioned to replace a stack of separate supplements, by subscription.', null, 'published') returning id into bid;
