  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Social Snowball', 10, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://im8health.com/pages/im8-ambassador-program.', 'https://im8health.com/pages/im8-ambassador-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'IM8 Ambassador Program', 'https://im8health.com/pages/im8-ambassador-program', 'https://im8health.com/pages/im8-ambassador-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://im8health.com/pages/im8-ambassador-program', 'official_site', 'affiliate', 'IM8''s official Ambassador Program page states ambassadors earn 10% commission on every new customer order through their link or code and says verbatim ''No caps on your earnings - ever''; its FAQ answers ''How much can I earn as an IM8 Ambassador?'' with ''There''s no limit on your earnings - the more you refer, the more you earn.'' Applications run through Social Snowball, payouts are monthly via PayPal or bank transfer after a 30-day hold, with a $100 minimum payout balance. The cap is verified uncapped on the brand''s own page.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://im8health.com/pages/im8-ambassador-program', 'official_site', 'contact', 'The same page publishes affiliates@im8health.com as the dedicated ambassador support contact, states the program is open internationally, and describes personal review of every application.', 'verified', now());
