  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 15, 13, 13, 8, 5, '{"niche_fit": "An all-in-one daily nutrition powder is a highly demo-able staple of wellness and routine content.", "ugc_evidence": "A structured ambassador program with dashboard, codes, free product and event perks; no Beacons creator count was verified on fetched pages, so saturation stays unknown.", "compensation": "10% per new order is mid-range, but the earnings cap is verified uncapped in the brand''s own words.", "contact_access": "Published affiliates@im8health.com ambassador support email.", "opportunity_availability": "Applications personally reviewed; open internationally.", "credibility": "NSF-certified product, co-founded with David Beckham and built by a listed health company, per the brand''s own pages and coverage."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Gundry MD', 'https://gundrymd.com', 'Supplement and lectin-free food brand founded by Dr. Steven Gundry, selling gut-health, probiotic and polyphenol formulas and Plant Paradox program products through its own store and national retail.', 'United States', 'published') returning id into bid;
