  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://wpengine.gundrymd.com/become-an-ambassador/', 'official_site', 'affiliate', 'Gundry MD''s official Ambassador Program page publishes a 20% commission on all referral sales through a personalized ambassador link, and its FAQ states verbatim: ''There''s no limit on the amount of referrals you can make or the commission you can earn.'' Joining is free, payments are issued monthly, and ambassadors join an online community with campaign access. The cap is verified uncapped on the brand''s own page.', 'verified', now());
